export const SCENARIO_EVENT_TYPES = [...new Set(Object.values(baseTypes).flat().map(([,type])=>type))];

export const scenarioEventCount = (key:ScenarioKey) => baseTypes[key].length;

const scenarioExperienceArea=(key:ScenarioKey)=>key==="library-canvas"?"library-canvas":key==="canvas-usage"?"canvas":key==="document-artifacts"||key==="output-workbench"?"outputs":key==="operational-safety"||key==="revision-race"||key==="replay-persona"?"operations":key==="async-return"||key==="promotion"||key==="taste-time"||key==="attention-friction"||key==="concurrency"?"intelligence":"document";

/**
 * A weighted-fair complete tour. Each focused narrative advances in proportion
 * to its own length, so the long Canvas grammar cannot hide the Library,
 * output, memory, or recovery stories near the end of a replay.
 */
export function buildComprehensiveScenario(streamId="theory:complete-capability",count=SCENARIOS.reduce((total,scenario)=>total+scenarioEventCount(scenario.key),0)) {
  const source:CreativeEvent[]=[];let cycle=0;
  while(source.length<count){
    const chapters=SCENARIOS.map((scenario)=>({scenario,events:buildScenarioRange(scenario.key,cycle*scenarioEventCount(scenario.key),scenarioEventCount(scenario.key)),position:0}));
    while(source.length<count&&chapters.some((chapter)=>chapter.position<chapter.events.length)){
      const available=chapters.filter((chapter)=>chapter.position<chapter.events.length).sort((left,right)=>left.position/left.events.length-right.position/right.events.length||SCENARIOS.indexOf(left.scenario)-SCENARIOS.indexOf(right.scenario));
      const chapter=available[0];const event=chapter.events[chapter.position++];
      source.push({...event,payload:{...event.payload,narrative_scenario:chapter.scenario.key,experience_area:scenarioExperienceArea(chapter.scenario.key),narrative_position:chapter.position,narrative_length:chapter.events.length}});
    }
    cycle+=1;
  }
  const start=Date.UTC(2026,0,5,9);let clock=start;
  return source.map((event,index)=>{
    if(index){const previous=source[index-1];const sourceGap=Math.max(1_000,Date.parse(event.occurredAt)-Date.parse(previous.occurredAt));clock+=Math.min(sourceGap,7*86_400_000);}
    const sequence=index+1;const eventId=`theory-complete-${sequence}`;const previousId=sequence>1?`theory-complete-${sequence-1}`:null;
    return{...event,eventId,streamId,sequence,occurredAt:new Date(clock).toISOString(),recordedAt:new Date(clock).toISOString(),correlationId:`corr-complete-${event.correlationId}`,causationId:previousId};
  });
}

export function buildReplayScenario(key:ReplayScenarioKey,count:number){return key==="complete-application-tour"?buildComprehensiveScenario("theory:complete-application-tour",count):buildScenario(key,count);}

